query.query:
mutation deletePost($id: ID!) {
  deletePost(id: "1 UNION SELECT * FROM users") {
    success
  }
}

mutation deletePost($id: ID!, $ignore: Boolean = true) {
  deletePost(id: $id, ignore: $ignore) @skip(if: $ignore) {
    success
  }
}

mutation deletePost($id: ID!, $ignore: Boolean = true, s: queryName = "deletePost") {
  $s(id: $id, ignore: $ignore) @skip(if: $ignore) {
    deletePost
  }
}

